export type StoryBlock = { type: 'heading' | 'paragraph'; text: string };

// Short standalone questions ("How so?", "What magic is this?") read as section headings.
const isHeading = (text: string) => text.length <= 40 && text.endsWith('?');

const toBlocks = (text: string): StoryBlock[] =>
  text
    .split(/\n\s*\n/)
    .map(paragraph => paragraph.trim())
    .filter(Boolean)
    .map(paragraph => ({
      type: isHeading(paragraph) ? 'heading' : 'paragraph',
      text: paragraph,
    }));

